function escapeHtml(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;");
}
function renderContacts(model) {
  const root = document.getElementById("root");
  const contacts = Array.isArray(model?.contacts) ? model.contacts : [];
  if (!contacts.length) {
    root.innerHTML = '<div class="empty">No Contacts selected.</div>';
    return;
  }
  root.innerHTML = contacts.map(contact => {
    const name = escapeHtml(contact.contact_name || contact.label || "Contact");
    const title = String(contact.title || "").trim();
    const heading = title ? `${name} (${escapeHtml(title)})` : name;
    const lines = [contact.phone ? `<div><strong>Phone:</strong> ${escapeHtml(contact.phone)}</div>` : "", contact.mobile ? `<div><strong>Mobile:</strong> ${escapeHtml(contact.mobile)}</div>` : "", contact.email ? `<div><strong>Email:</strong> ${escapeHtml(contact.email)}</div>` : "", contact.notes ? `<div class="notes"><strong>Notes:</strong> ${escapeHtml(contact.notes)}</div>` : ""].filter(Boolean).join("");
    const cardClass = contact.deleted ? "contact-card deleted" : !contact.active ? "contact-card inactive" : "contact-card";
    const statusClass = contact.deleted ? "deleted" : contact.active === false ? "inactive" : "";
    return `
	<div class="contact-card">
		<div class="contact-heading ${statusClass}">
			${heading}
		</div>
		${lines}
	</div>
`;
  }).join("");
}
appsmith.onReady(() => {
  renderContacts(appsmith.model);
  appsmith.onModelChange(newModel => {
    renderContacts(newModel);
  });
});

